// Des: Halt guard: login, captcha, unsafe pages stop work
// Flo: stored halt flag > page text lowercased > match QR names, needs words, unsafe words > store flag + class > typed error
// I/O: page text + Conf + Reg (caller) > Verd; error Halted or NeedLogin, halt flag + class in state db
// ===================================================================
const std = @import("std"); const conf = @import("cf-conf-load.zig"); const lab = @import("cf-labl-load.zig"); const snap = @import("ru-page-snap.zig"); const cdp = @import("nt-cdpz-sock.zig"); const data = @import("st-stat-data.zig");
pub const Class = enum { none, need, unsf };
pub const Verd = struct { kind: enum { okay, login, need, unsf }, word: []const u8 = "" };
fn lowCp(cpz: u21) u21 { if (cpz >= 'A' and cpz <= 'Z') return cpz + 32; if (cpz >= 0xC0 and cpz <= 0xDE and cpz != 0xD7) return cpz + 32; if (cpz == 0x110 or cpz == 0x128 or cpz == 0x168 or cpz == 0x1A0 or cpz == 0x1AF or cpz == 0x102) return cpz + 1; if (cpz >= 0x1EA0 and cpz <= 0x1EF8 and cpz % 2 == 0) return cpz + 1; return cpz; }
pub fn lowFold(aren: std.mem.Allocator, text: []const u8) ![]u8 { var out: std.ArrayList(u8) = .empty; var itr = (std.unicode.Utf8View.init(text) catch return aren.dupe(u8, text)).iterator(); while (itr.nextCodepoint()) |cpz| { var buf: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(lowCp(cpz), &buf) catch continue; try out.appendSlice(aren, buf[0..lenz]); } return out.items; }
fn hits(aren: std.mem.Allocator, low: []const u8, words: []const []const u8) !?[]const u8 { for (words) |wrd| { if (wrd.len == 0) continue; const wlo = try lowFold(aren, wrd); if (std.mem.find(u8, low, wlo) != null) return wrd; } return null; }
pub fn judge(aren: std.mem.Allocator, text: []const u8, qrnames: []const []const u8, needw: []const []const u8, unsfw: []const []const u8) !Verd { const low = try lowFold(aren, text); if (try hits(aren, low, qrnames)) |wrd| { _ = wrd; return .{ .kind = .login }; } if (try hits(aren, low, unsfw)) |wrd| return .{ .kind = .unsf, .word = wrd }; if (try hits(aren, low, needw)) |wrd| return .{ .kind = .need, .word = wrd }; return .{ .kind = .okay }; }
fn joined(aren: std.mem.Allocator, reg: *const lab.Reg, key: []const u8, extra: []const []const u8) ![]const []const u8 { var out: std.ArrayList([]const u8) = .empty; if (reg.get(key)) |ent| { for (ent.vi) |nam| try out.append(aren, nam); for (ent.en) |nam| try out.append(aren, nam); } for (extra) |nam| try out.append(aren, nam); return out.items; }
pub fn check(aren: std.mem.Allocator, cfg: conf.Conf, reg: *const lab.Reg, text: []const u8) !Verd { return judge(aren, text, try joined(aren, reg, "qrcd_page", &.{}), try joined(aren, reg, "halt_need", &.{}), try joined(aren, reg, "halt_unsf", cfg.halt_word_list)); }
pub fn classOf(sto: *data.Stor, aren: std.mem.Allocator) !Class { const val = try sto.metaGet(aren, "halt_class") orelse return .none; if (std.mem.eql(u8, val, "need")) return .need; if (std.mem.eql(u8, val, "unsf")) return .unsf; return .none; }
pub fn guardText(aren: std.mem.Allocator, cfg: conf.Conf, reg: *const lab.Reg, sto: *data.Stor, now_ms: i64, text: []const u8) !void { if (try sto.haltGet(aren)) |_| return error.Halted; const ver = try check(aren, cfg, reg, text); switch (ver.kind) { .okay => {}, .login => return error.NeedLogin, .need, .unsf => { try sto.haltSet(now_ms, ver.word); try sto.metaSet("halt_class", if (ver.kind == .need) "need" else "unsf"); try sto.logAdd(now_ms, "halt", "guard", ver.word); return error.Halted; } } }
pub fn pageOf(aren: std.mem.Allocator, conn: *cdp.Conn, reg: *const lab.Reg) ![]const u8 { return snap.pageTextExcl(aren, conn, &.{ reg.ext.msg_sel, reg.ext.chat_sel, reg.ext.comp_sel }); }
pub fn guard(aren: std.mem.Allocator, cfg: conf.Conf, reg: *const lab.Reg, sto: *data.Stor, conn: *cdp.Conn, now_ms: i64) !void { if (try sto.haltGet(aren)) |_| return error.Halted; const txt = try pageOf(aren, conn, reg); try guardText(aren, cfg, reg, sto, now_ms, txt); }
